// ─────────────────────────────────────────────────────────────────────────
//  01 · first matching rule★★☆
//  concepts: first match wins · * and ** segments · ROLE_ prefix · 401 versus 403
// ─────────────────────────────────────────────────────────────────────────

import static bootcamp.Check.*;

import java.util.*;

class Exercise {

    enum Access { PERMIT_ALL, DENY_ALL, AUTHENTICATED, HAS_ROLE, HAS_AUTHORITY }

    /** One authorizeHttpRequests rule; method null = any method; value = the role or authority, else null. */
    record Rule(String method, String pattern, Access access, String value) {
        static Rule of(String pattern, Access access) { return new Rule(null, pattern, access, null); }
        static Rule role(String pattern, String role) { return new Rule(null, pattern, Access.HAS_ROLE, role); }
    }

    /** A signed-in caller and the authorities it was granted. */
    record User(String name, Set<String> authorities) {}

    static List<String> segments(String s) {
        var out = new ArrayList<String>();
        for (var part : s.split("/")) if (!part.isEmpty()) out.add(part);
        return out;
    }

    static boolean match(List<String> pat, int i, List<String> path, int j) {
        if (i == pat.size()) return j == path.size();
        String p = pat.get(i);
        if (p.equals("**")) {
            for (int k = j; k <= path.size(); k++) if (match(pat, i + 1, path, k)) return true;
            return false;
        }
        if (j == path.size()) return false;
        return (p.equals("*") || p.equals(path.get(j))) && match(pat, i + 1, path, j + 1);
    }

    static boolean matches(String pattern, String path) {
        return match(segments(pattern), 0, segments(path), 0);
    }

    static int decide(List<Rule> rules, String method, String path, User user) {
        boolean allowed = false;
        for (Rule rule : rules) {
            if (rule.method() != null && !rule.method().equals(method)) continue;
            if (!matches(rule.pattern(), path)) continue;
            Set<String> granted = user == null ? Set.of() : user.authorities();
            allowed = switch (rule.access()) {
                case PERMIT_ALL -> true;
                case DENY_ALL -> false;
                case AUTHENTICATED -> user != null;
                case HAS_ROLE -> granted.contains("ROLE_" + rule.value());
                case HAS_AUTHORITY -> granted.contains(rule.value());
            };
            break;
        }
        if (allowed) return 200;
        return user == null ? 401 : 403;
    }

    static final User NOBODY_SPECIAL = new User("cy", Set.of());
    static final User ADMIN = new User("ana", Set.of("ROLE_ADMIN"));

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("ant patterns: * is one segment, ** is any number of them", () -> {
            eq(List.of(matches("/api/**", "/api"), matches("/api/**", "/api/a/b"), matches("/api/*", "/api/a"),
                       matches("/api/*", "/api/a/b"), matches("/api/*", "/api"), matches("/api/orders", "/api/orders/7")),
               List.of(true, true, true, false, false, false));
        });
        test("the first matching rule decides, even when a later one is more specific", () -> {
            var rules = List.of(Rule.of("/**", Access.AUTHENTICATED), Rule.role("/admin/**", "ADMIN"));
            eq(decide(rules, "GET", "/admin/users", NOBODY_SPECIAL), 200);
        });
        test("with the specific rule first, a non-admin is forbidden and an admin allowed", () -> {
            var rules = List.of(Rule.role("/admin/**", "ADMIN"), Rule.of("/**", Access.AUTHENTICATED));
            eq(List.of(decide(rules, "GET", "/admin/users", NOBODY_SPECIAL), decide(rules, "GET", "/admin/users", ADMIN)), List.of(403, 200));
        });
        test("hasRole needs the ROLE_ prefix; hasAuthority wants the exact string", () -> {
            var plain = new User("bo", Set.of("ADMIN", "orders:write"));
            var byRole = List.of(Rule.role("/admin/**", "ADMIN"));
            var byAuthority = List.of(new Rule(null, "/orders/**", Access.HAS_AUTHORITY, "orders:write"));
            eq(List.of(decide(byRole, "GET", "/admin/x", plain), decide(byAuthority, "POST", "/orders/9", plain)), List.of(403, 200));
        });
        test("a refused anonymous caller gets 401, a refused known caller 403", () -> {
            var rules = List.of(Rule.of("/internal/**", Access.DENY_ALL), Rule.of("/**", Access.AUTHENTICATED));
            eq(List.of(decide(rules, "GET", "/internal/jobs", null), decide(rules, "GET", "/internal/jobs", ADMIN), decide(rules, "GET", "/orders", null)),
               List.of(401, 403, 401));
        });
        test("a rule for one method does not cover the others", () -> {
            var rules = List.of(new Rule("GET", "/api/health", Access.PERMIT_ALL, null), Rule.of("/**", Access.AUTHENTICATED));
            eq(List.of(decide(rules, "GET", "/api/health", null), decide(rules, "POST", "/api/health", null)), List.of(200, 401));
        });
        test("a path that no rule matches is refused (boundary)", () -> {
            var rules = List.of(Rule.of("/api/**", Access.AUTHENTICATED));
            eq(List.of(decide(rules, "GET", "/other", ADMIN), decide(rules, "GET", "/other", null)), List.of(403, 401));
        });
        System.exit(report());
    }
    // ─── end tests ───────────────────────────────────────────────────────
}

drills.explanation:
Ant matching is a small recursion over segments, where `**` tries every possible length:

```java
if (p.equals("**")) {
    for (int k = j; k <= path.size(); k++) if (match(pat, i + 1, path, k)) return true;
    return false;
}
if (j == path.size()) return false;
return (p.equals("*") || p.equals(path.get(j))) && match(pat, i + 1, path, j + 1);
```

`decide` walks the rules in order and stops at the first one whose method and pattern match; the access decides allowed, and a refusal is 401 for `null` (anonymous) and 403 otherwise. The tests catch the plausible wrong evaluators: picking the most specific rule instead of the first (the misordered config looks safe), `hasRole` without the `ROLE_` prefix (plain `ADMIN` gets in), 403 for every refusal (an anonymous caller should be asked to authenticate), `*` that swallows several segments, and rules that ignore their method.

