    static final Controller WHO_AM_I = r -> "user=" + SecurityContext.current();
    static final Controller ANA_ONLY = r -> {
        if (!"ana".equals(SecurityContext.current())) throw new AccessDeniedException("Access Denied");
        return "secret";
    };
    static Request get(String path, String authorization) {
        return new Request("GET", path, authorization == null ? Map.of() : Map.of("Authorization", authorization));
    }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("a valid bearer token makes its user current inside the controller", () -> {
            eq(handle(get("/me", "Bearer t-ana"), WHO_AM_I, TOKENS), new Response(200, Map.of(), "user=ana"));
        });
        test("no Authorization header: the request goes on as anonymous", () -> {
            eq(handle(get("/me", null), WHO_AM_I, TOKENS), new Response(200, Map.of(), "user=null"));
        });
        test("an unknown token or another scheme is refused with 401 before the controller runs", () -> {
            var calls = new int[1];
            Controller counting = r -> { calls[0]++; return "ran"; };
            var bad = handle(get("/me", "Bearer t-forged"), counting, TOKENS);
            var basic = handle(get("/me", "Basic YW5hOnB3"), counting, TOKENS);
            eq(List.of(bad.status(), bad.headers().get("WWW-Authenticate"), basic.status(), calls[0]), List.of(401, "Bearer error=\"invalid_token\"", 401, 0));
        });
        test("access denied for a known caller is 403", () -> {
            eq(handle(get("/secret", "Bearer t-bo"), ANA_ONLY, TOKENS), new Response(403, Map.of(), ""));
        });
        test("access denied for an anonymous caller is a 401 challenge", () -> {
            eq(handle(get("/secret", null), ANA_ONLY, TOKENS), new Response(401, Map.of("WWW-Authenticate", "Bearer"), ""));
        });
        test("the context is cleared after each request: the next one on this thread is anonymous", () -> {
            handle(get("/me", "Bearer t-ana"), WHO_AM_I, TOKENS);
            eq(List.of(handle(get("/me", null), WHO_AM_I, TOKENS).body(), String.valueOf(SecurityContext.current())), List.of("user=null", "null"));
        });
        test("the context is cleared even when the controller throws (boundary)", () -> {
            Controller broken = r -> { throw new IllegalStateException("database is down"); };
            raises(IllegalStateException.class, () -> handle(get("/me", "Bearer t-ana"), broken, TOKENS), "database is down");
            eq(String.valueOf(SecurityContext.current()), "null");
        });
        System.exit(report());
    }
    // ─── end tests ───────────────────────────────────────────────────────
}
